/*
 *  Unit tests run against the fixture generated by real Qt 5.15
 *  (QSettings("Shanti", "Shanti"); captured pre-rebrand as QSettings("OpenBangla", "Keyboard")) — see tests/fixtures/README.md
 *  for the regeneration procedure.
 */

use shanti_config::Config;

const FIXTURE: &str = include_str!("fixtures/keyboard.conf");

fn fixture() -> Config {
    Config::parse(FIXTURE)
}

/// Every boolean key, with the value Qt 5.15 wrote into the fixture
/// (deliberately NOT all defaults — several are flipped to catch parser
/// confusion between the written value and the Settings.cpp default).
const FIXTURE_BOOLS: &[(&str, bool)] = &[
    ("settings/EnterKeyClosesPrevWin", false),
    ("settings/FixedLayout/ShowPrevWin", true),
    ("settings/FixedLayout/AutoVowelForm", false),
    ("settings/FixedLayout/AutoChandraPos", true),
    ("settings/FixedLayout/TraditionalKar", true),
    ("settings/FixedLayout/NumberPad", true),
    ("settings/FixedLayout/OldReph", false),
    ("settings/CandidateWin/Horizontal", true),
    ("settings/CandidateWin/Phonetic", false),
    ("settings/PreviewWin/IncludeEnglish", true),
    ("settings/FixedLayout/OldKarOrder", true),
    ("settings/ANSI", false),
    ("settings/SmartQuoting", true),
    ("settings/PreviousUserDataRemains", true),
    ("window/visibility/TopBar", true),
];

#[test]
fn reads_every_boolean_key_with_qt_parity() {
    let config = fixture();
    for (key, expected) in FIXTURE_BOOLS {
        assert_eq!(config.get_bool(key, !*expected), *expected, "key {key}");
    }
}

/// Missing keys (and a valueless config) fall back to the exact
/// Settings.cpp defaults, mirroring QSettings behavior.
#[test]
fn missing_keys_return_settings_dot_cpp_defaults() {
    let config = Config::parse("");
    for (key, dflt) in FIXTURE_BOOLS {
        assert_eq!(config.get_bool(key, *dflt), *dflt, "key {key}");
    }
    assert_eq!(config.get_uint("settings/TrayInfoCount", 0), 0);
    assert_eq!(
        config.get_string("settings/PreviewWin/IncludeEnglish", "?"),
        "?"
    );
}

#[test]
fn reads_uint_keys() {
    let config = fixture();
    assert_eq!(config.get_uint("settings/TrayInfoCount", 0), 3);
}

#[test]
fn populated_config_falls_back_for_missing_keys_and_respects_written_values() {
    let config = fixture();
    assert_eq!(config.get_string("settings/Nonexistent/Key", "fallback"), "fallback");
    assert!(config.get_bool("settings/Nonexistent/Key", true), "fallback");
    // A flipped fixture value must not be confused with its default.
    assert!(!config.get_bool("settings/FixedLayout/AutoVowelForm", true));
}

#[test]
fn empty_store_yields_all_defaults() {
    let config = Config::parse(" unrelated [stuff");
    for (key, dflt) in FIXTURE_BOOLS {
        assert_eq!(config.get_bool(key, *dflt), *dflt, "key {key}");
    }
    assert_eq!(config.get_uint("settings/TrayInfoCount", 0), 0);
    assert_eq!(config.get_string("layout/path", "avro_phonetic"), "avro_phonetic");
}

#[test]
fn point_values_are_kept_raw_for_the_gui_phase() {
    let config = fixture();
    assert_eq!(config.get_string("window/positions/TopBar", ""), "@Point(120 240)");
}

#[test]
fn comments_and_blank_lines_are_ignored() {
    let config = Config::parse(
        "; comment\n# comment\n\n[layout]\npath=avro_phonetic\n",
    );
    assert_eq!(config.get_string("layout/path", "?"), "avro_phonetic");
}

#[test]
fn whitespace_around_keys_and_values_is_trimmed() {
    let config = Config::parse("[layout]\n  path = avro_phonetic  \n");
    assert_eq!(config.get_string("layout/path", "?"), "avro_phonetic");
}
